        proj = {"_id": 0, "description": 0, "specs": 0}
        same_cat = await db.shop_products.find({"active": True, "category": d.get("category", ""), "id": {"$ne": d["id"]}}, proj).sort([("featured", -1), ("sort", 1)]).limit(40).to_list(40)
