        p0 = d.get("price", 0) or 0
        sim = sorted([r for r in same_cat], key=lambda r: (0 if r.get("brand") == d.get("brand") else 1, abs((r.get("price", 0) or 0) - p0)))[:n]
        seen = {r["id"] for r in sim}
        other = [r for r in same_brand if r["id"] not in seen][:n]
