        for p, _i in ready:
            await db.shop_products.update_one({"id": p["id"]}, {"$set": {f"market_sync.{mk}.batch": batch, f"market_sync.{mk}.at": _now(), f"market_sync.{mk}.error": "",
                                                                          f"market_sync.{mk}.created_sent": True}})
        return {**res, "sent": len(items), "batch": batch}

