        need_firm()
        title = " ".join(str(payload.get("title") or "").split())[:80]
        if len(title) < 2:
            raise HTTPException(422, "Sayfa başlığı yazın")
        tr = str.maketrans("çğıöşüÇĞİÖŞÜ", "cgiosuCGIOSU")
