def seo_block(ctx, title, desc, slug="", kind="home", extra_ld=None):
    """Temaya/sektöre özgü SEO: açıklama, canonical, Open Graph, JSON-LD. Alan adı {{H}} yer tutucusuyla gelir (seo_finish doldurur)."""
